'use strict';

// Writes ../../casetables.go: what String.prototype.toLowerCase does in
// this Node, for every code point. See README.md.
//
//   lowerCase     code points whose lower case is another text
//   casedRanges   letters that make a capital sigma after them a final one
//   ignoredRanges characters the final-sigma rule looks through

const fs = require('fs');
const path = require('path');

const SIGMA = 'Σ';
const FINAL = 'ς';

const lower = [];
const cased = [];
const ignored = [];
for (let cp = 0; cp <= 0x10ffff; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    const ch = String.fromCodePoint(cp);
    const low = ch.toLowerCase();
    if (low !== ch && cp !== 0x3a3) lower.push([cp, low]);
    const after = (ch + SIGMA).toLowerCase().endsWith(FINAL);
    const through = ('a' + ch + SIGMA).toLowerCase().endsWith(FINAL);
    if (after) cased.push(cp);
    else if (through) ignored.push(cp);
    // The same two sets decide what may follow a final sigma
    const before = ('a' + SIGMA + ch).toLowerCase().startsWith('a' + FINAL);
    if (before !== !after) throw new Error(`U+${cp.toString(16)}: the rule for what follows a sigma differs from the rule for what precedes it`);
}

function ranges(list) {
    const out = [];
    for (const cp of list) {
        const last = out[out.length - 1];
        if (last && last[1] === cp - 1) last[1] = cp;
        else out.push([cp, cp]);
    }
    return out;
}

const hex = (n) => '0x' + n.toString(16).toUpperCase();
const lines = [];
lines.push('// Code generated by testdata/nodeoracle/casing.js from Node ' + process.version + ' (Unicode ' + process.versions.unicode + '). DO NOT EDIT.');
lines.push('');
lines.push('package ssrfguard');
lines.push('');
lines.push('// lowerCase holds every character whose lower case is another text.');
lines.push('var lowerCase = map[rune]string{');
for (const [cp, low] of lower) {
    const text = Array.from(low).map((c) => '\\U' + c.codePointAt(0).toString(16).toUpperCase().padStart(8, '0')).join('');
    lines.push(`\t${hex(cp)}: "${text}",`);
}
lines.push('}');
lines.push('');
lines.push('// casedRanges are the letters after which a capital sigma is a final one.');
lines.push('var casedRanges = [][2]rune{');
for (const [a, b] of ranges(cased)) lines.push(`\t{${hex(a)}, ${hex(b)}},`);
lines.push('}');
lines.push('');
lines.push('// ignoredRanges are the characters the final-sigma rule looks through.');
lines.push('var ignoredRanges = [][2]rune{');
for (const [a, b] of ranges(ignored)) lines.push(`\t{${hex(a)}, ${hex(b)}},`);
lines.push('}');
lines.push('');
fs.writeFileSync(path.join(__dirname, '..', '..', 'casetables.go'), lines.join('\n'));
console.log(lower.length, 'lower-case mappings,', ranges(cased).length, 'cased ranges,', ranges(ignored).length, 'ignored ranges');
